[
  {
    "front": "Kinesis Data Streams được Amazon Connect sử dụng để stream loại dữ liệu gì?",
    "back": "Contact records và agent events (bao gồm agent login, logout, status change, và heartbeat)."
  },
  {
    "front": "Producer trong Kinesis Data Streams là gì?",
    "back": "Là nguồn tạo và gửi payloads đến Kinesis stream trong thời gian gần thực (near real time)."
  },
  {
    "front": "Consumer trong Kinesis Data Streams là gì?",
    "back": "Là ứng dụng hoặc dịch vụ đọc và xử lý payloads từ Kinesis stream."
  },
  {
    "front": "Fan out data streaming architecture là gì?",
    "back": "Kiến trúc phân phối payloads đến nhiều outputs hoặc consumers đồng thời."
  },
  {
    "front": "Vai trò của Kinesis trong kiến trúc microservice là gì?",
    "back": "Hoạt động như kênh truyền có tính khả dụng cao để stream messages giữa data producers và data consumers."
  },
  {
    "front": "AWS Lambda có thể làm gì với Kinesis Data Streams?",
    "back": "Triển khai logic chuyển đổi dữ liệu (data transformation) cho cả Kinesis Data Streams và Amazon Data Firehose."
  },
  {
    "front": "Kinesis Firehose hỗ trợ chuyển đổi định dạng dữ liệu nào?",
    "back": "Chuyển đổi từ JSON sang Apache Parquet hoặc Apache ORC trước khi lưu vào Amazon S3."
  },
  {
    "front": "Kinesis Data Streams mã hóa dữ liệu như thế nào?",
    "back": "Sử dụng server-side encryption với customer managed keys. Dữ liệu được mã hóa trước khi ghi và giải mã sau khi truy xuất."
  },
  {
    "front": "Amazon Connect cần quyền gì để gửi dữ liệu qua Kinesis Data Streams?",
    "back": "Cần quyền sử dụng customer managed keys và service linked role phải có quyền sử dụng KMS key mã hóa data stream."
  },
  {
    "front": "Amazon Connect Customer Profiles hỗ trợ xuất dữ liệu như thế nào?",
    "back": "Hỗ trợ xuất real-time unified customer profiles đến Kinesis Data Streams."
  }
]
